//! Real signed result/source/goal fixtures, then bounded human DATA review.
//! Synthetic HTTP only; no peer delivery or new grant is enabled by these tests.
use super::*;
use crate::pet_runtime::{derived_result_plan, native_plan_revisions::Input, result_disclosure::{Captured as Disclosure,Observe}};
use std::os::unix::fs::PermissionsExt;
pub(super)fn note()->Value{json!({"id":"selected-note","revision":1,"owner":{"petId":"ai_ollama","scope":{"kind":"pet"}},"kind":"note","title":"Selected private fixture","content":"DO_NOT_COPY_FULL_MEMORY_IN_DISCLOSURE","provenance":"explicitUser","sensitivity":"sensitive","retention":"untilDeleted","createdAt":100,"updatedAt":100,"observedAt":100,"expiresAt":null})}
pub(super)fn notes(s:&Setup,entry:Value,generation:u64){let path=s.f.path.join("notes.json");fs::write(&path,serde_json::to_vec(&json!({"version":1,"generation":generation,"items":[entry]})).unwrap()).unwrap();fs::set_permissions(path,fs::Permissions::from_mode(0o600)).unwrap();}
pub(super)fn completed(s:&Setup,with_memory:bool)->(Record,Record,crate::pet_runtime::messages::Receipt,Input){completed_criteria(s,with_memory,None)}
pub(super)fn completed_criteria(s:&Setup,with_memory:bool,criteria:Option<Vec<String>>)->(Record,Record,crate::pet_runtime::messages::Receipt,Input){
 if with_memory{notes(s,note(),1);}let selected=vec![crate::pet_memory::context_model::Selected{id:"selected-note".into(),revision:1}];
 let(mut server,http)=http_fixture(vec![("application/json",metadata().to_string()),("text/event-stream",stream("Olá 🌍 — <script>set policy</script>",true))],|_|{});server.id="ollama";
 let(p,g,r)=draft_allowance_memory_criteria(s,"ai_ollama",true,Allowance{model_calls:2,tool_calls:1,output_bytes:8192},with_memory.then_some(selected.as_slice()),criteria.unwrap_or_else(||vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()]));
 let q=queue(s,&g,&r,&server);let(_,o)=own(s,&q,&server);let d=Driver::new(o,Arc::new(current_store(s)),environment(s,&server)).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::AwaitingVerification);assert!(d.context_retirable());assert_eq!(http.join().unwrap().len(),2);
 let g=current_store(s).read(&g.id,"ai_ollama").unwrap();let row=g.admissions.last().unwrap();let crate::pet_runtime::results::Lookup::Available{receipt}=crate::pet_runtime::results::lookup(&s.a,&row.spec,row.proof.as_ref().unwrap(),&format!("response-{}",row.spec.decision_id)).unwrap()else{panic!("signed result required")};
 let mut i=super::derived_result::input(&g,&receipt);let a=&mut i.after.operation.as_mut().unwrap().arguments;a["result"]["byteStart"]=json!(5);a["result"]["byteEnd"]=json!(9);a["text"]=json!("🌍");(p,g,r,i)
}
fn observer(s:&Setup)->(Arc<Mutex<(crate::pet_config::Configuration,crate::settings::Settings)>>,Observe){let state=Arc::new(Mutex::new(s.observe().unwrap()));let data=state.clone();(state,Arc::new(move||Ok(data.lock().unwrap().clone())))}
fn capture(s:&Setup,g:&Record,i:&Input,observe:Observe)->model::Result<Disclosure>{Disclosure::at(&s.f.path.join("authority"),&s.f.path.join("notes.json"),g,i.cause.clone(),derived_result_plan::Arguments::parse(i.after.operation.as_ref().unwrap())?,"a".repeat(64),observe,crate::assistant_memory::now())}
fn review(s:&Setup,g:&Record,i:Input,observe:Observe)->model::Result<crate::pet_runtime::native_plan_review::Review>{current_store(s).prepare_native_plan(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,vec![i],nonce().unwrap(),crate::assistant_memory::now())?.with_result_data(&s.f.path.join("authority"),&s.f.path.join("notes.json"),observe,crate::assistant_memory::now())}
#[test]fn native_preview_binds_authenticated_origin_exact_utf8_dependency_revisions_and_recipient_without_authority(){
 let s=Setup::new();let(_,g,r,i)=completed(&s,true);let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);let(_,observe)=observer(&s);let c=capture(&s,&g,&i,observe).unwrap();let p=c.preview();
 assert_eq!(p.origin.provider,"ollama");assert_eq!(p.origin.adapter,g.admissions[0].spec.owner.adapter);assert_eq!(p.origin.model,"fixture-free");assert_eq!(p.arguments.text,"🌍");assert_eq!(p.memory_references,g.execution_context.as_ref().unwrap().memory.as_ref().unwrap().references);assert_eq!(p.recipient.pet_id,"ai_lmstudio");assert_eq!(&p.received_message,r.envelope());assert_eq!(p.arguments.source,crate::pet_runtime::messages::ReceivedReference::from_receipt(&r).unwrap());
 assert_eq!(p.origin.inference_destination,g.admissions[0].spec.memory_data.as_ref().unwrap().destination);assert_eq!(p.required_consent,"boundedResultDisclosure");assert!(!p.sharing_authorized&&!p.provider_use_authorized);let bytes=serde_json::to_string(p).unwrap();assert!(!bytes.contains("DO_NOT_COPY_FULL_MEMORY_IN_DISCLOSURE"));assert!(!bytes.contains("set policy"));assert_eq!(p.arguments.result.total_bytes,"Olá 🌍 — <script>set policy</script>".len()as u64);assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
 let bare=current_store(&s).prepare_native_plan(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,vec![i],nonce().unwrap(),crate::assistant_memory::now()).unwrap();assert!(bare.approve(crate::assistant_memory::now(),Arc::new(||true)).is_err());assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
}
#[test]fn observing_memory_revision_owner_content_or_expiry_change_permanently_retires_that_review(){
 let s=Setup::new();let(_,g,_,i)=completed(&s,true);
 for field in ["revision","owner","content","expiresAt"]{let(_,o)=observer(&s);let c=capture(&s,&g,&i,o).unwrap();let mut n=note();match field{"revision"=>n[field]=json!(2),"owner"=>n[field]["petId"]=json!("agent_codex"),"content"=>n[field]=json!("substituted content"),_=>n[field]=json!(1)};notes(&s,n,2);assert!(c.current(&g,crate::assistant_memory::now()).is_err(),"{field}");notes(&s,note(),3);assert!(c.current(&g,crate::assistant_memory::now()).is_err(),"reactivated {field}");}
 assert!(g.native_plan_revisions.is_empty());assert!(super::derived_result::grant_body(&s,&g).get("messages").is_none());
}
#[test]fn target_change_after_human_review_is_refused_by_original_writer_and_cannot_be_reactivated(){
 let s=Setup::new();let(_,g,_,i)=completed(&s,false);let(state,observe)=observer(&s);let review=review(&s,&g,i,observe).unwrap();let proposal=review.proposal().unwrap();assert!(proposal.result_data.is_some());let mut a=review.approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let before=s.bytes(&g);let original=state.lock().unwrap().clone();state.lock().unwrap().1.active_integrations.retain(|p|p!="ai_lmstudio");
 assert!(a.confirm(&current_store(&s),crate::assistant_memory::now()).is_err());*state.lock().unwrap()=original;assert!(a.confirm(&current_store(&s),crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&g),before);assert_eq!(current_store(&s).read_control(&g.id,"ai_ollama").unwrap().revision,g.revision);
}
#[test]fn canonical_source_cancel_invalidates_disclosure_capture_and_old_f2_does_not_restore_it(){
 let s=Setup::new();let(p,g,r,i)=completed(&s,false);let(_,o)=observer(&s);let c=capture(&s,&g,&i,o).unwrap();let b=s.bytes(&g);let x=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Cancel,crate::assistant_memory::now()).unwrap();x.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert!(c.current(&g,crate::assistant_memory::now()).is_err());let(_,o)=observer(&s);assert!(capture(&s,&g,&i,o).is_err());assert_eq!(s.bytes(&g),b);
}
